// pyint.mjs — replicates Python's built-in int(str) parsing behavior.
// Accepts: optional surrounding whitespace, an optional +/- sign, decimal
// digits with single underscores allowed only between digits (PEP 515).

const INT_RE = /^\s*[+-]?\d(?:_?\d)*\s*$/;

/**
 * Parse a string the way Python's int() does.
 * Returns the integer value, or null if the string is not a valid int literal.
 */
export function parsePyInt(text) {
  if (typeof text !== 'string' || !INT_RE.test(text)) {
    return null;
  }
  // Underscores are digit separators; strip them before numeric conversion.
  const normalized = text.trim().replace(/_/g, '');
  return parseInt(normalized, 10);
}

