// pybytes.mjs — replicates Python's repr() of a bytes object,
// which is exactly what print(b'...') produces.

const BACKSLASH = 0x5c;
const SINGLE_QUOTE = 0x27;
const DOUBLE_QUOTE = 0x22;
const TAB = 0x09;
const NEWLINE = 0x0a;
const CARRIAGE_RETURN = 0x0d;
const SPACE = 0x20;
const DEL = 0x7f;

/**
 * Format a Buffer (or byte array) like Python's repr(bytes).
 * Quote selection follows CPython: single quotes by default, double quotes
 * only when the data contains a single quote but no double quote.
 */
export function reprBytes(buffer) {
  const bytes = Array.from(buffer);
  const hasSingle = bytes.includes(SINGLE_QUOTE);
  const hasDouble = bytes.includes(DOUBLE_QUOTE);
  const quote = hasSingle && !hasDouble ? '"' : "'";
  const quoteCode = quote === "'" ? SINGLE_QUOTE : DOUBLE_QUOTE;

  let out = 'b' + quote;
  for (const b of bytes) {
    if (b === BACKSLASH) {
      out += '\\\\';
    } else if (b === quoteCode) {
      out += '\\' + quote;
    } else if (b === TAB) {
      out += '\\t';
    } else if (b === NEWLINE) {
      out += '\\n';
    } else if (b === CARRIAGE_RETURN) {
      out += '\\r';
    } else if (b >= SPACE && b < DEL) {
      out += String.fromCharCode(b);
    } else {
      out += '\\x' + b.toString(16).padStart(2, '0');
    }
  }
  return out + quote;
}

