// construct.mjs — minimal re-implementation of the parts of the Python
// `construct` library used by the source script: Int8ul and Struct.build().

/** Error mirroring construct.core.FormatFieldError. */
export class FormatFieldError extends Error {
  constructor(message, fieldName, value) {
    super(message);
    this.name = 'FormatFieldError';
    this.fieldName = fieldName;
    this.value = value;
  }
}

/**
 * Int8ul: unsigned 8-bit integer, little-endian (irrelevant at 1 byte).
 * Python: construct.Int8ul
 */
export class Int8ul {
  constructor() {
    this.structFormat = '<B';
    this.min = 0;
    this.max = 255;
  }

  build(value) {
    if (!Number.isInteger(value) || value < this.min || value > this.max) {
      throw new FormatFieldError(
        `struct '${this.structFormat}' error during building, given value ${value}`,
        null,
        value,
      );
    }
    return Buffer.from([value]);
  }
}

/**
 * Struct: an ordered collection of named fields.
 * Python: construct.Struct("name" / Type, ...)
 * build(obj) concatenates each field's built bytes in declaration order.
 */
export class Struct {
  /**
   * @param {Array<[string, Int8ul]>} fields [name, type] pairs in order.
   */
  constructor(...fields) {
    this.fields = fields;
  }

  build(obj) {
    const chunks = [];
    for (const [name, type] of this.fields) {
      try {
        chunks.push(type.build(obj[name]));
      } catch (err) {
        if (err instanceof FormatFieldError && err.fieldName === null) {
          err.fieldName = name;
          err.message =
            `Error in path (building) -> ${name}\n` + err.message;
        }
        throw err;
      }
    }
    return Buffer.concat(chunks);
  }
}

