// argparse.mjs — minimal re-implementation of the Python argparse behavior
// used by the source script: required options of type=int, --opt=value form,
// -h/--help, and argparse's error/exit-code conventions.

// Matches argparse's _negative_number_matcher: tokens that look like
// negative numbers are treated as values, not options.
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

function isOptionLike(token) {
  return token.startsWith('-') && token !== '-' && !NEGATIVE_NUMBER_RE.test(token);
}

export class ArgumentParser {
  /**
   * @param {string} prog program name shown in usage/error messages.
   */
  constructor(prog) {
    this.prog = prog;
    this.options = []; // [{name, dest, metavar, typeFn, required}]
  }

  /**
   * addArgument('--a', {type: parseFn, required: true})
   * Only the long-option form used by the source script is supported.
   */
  addArgument(name, { type = null, required = false } = {}) {
    const dest = name.replace(/^--/, '');
    const metavar = dest.toUpperCase();
    this.options.push({ name, dest, metavar, typeFn: type, required });
  }

  usage() {
    const parts = this.options.map(
      (o) => (o.required ? `${o.name} ${o.metavar}` : `[${o.name} ${o.metavar}]`),
    );
    return `usage: ${this.prog} [-h] ${parts.join(' ')}`;
  }

  /** Print help to stdout and exit 0, like argparse's -h/--help. */
  printHelp() {
    let out = this.usage() + '\n\noptions:\n';
    out += '  -h, --help  show this help message and exit\n';
    for (const o of this.options) {
      out += `  ${o.name} ${o.metavar}\n`;
    }
    process.stdout.write(out);
  }

  /** Print usage + error to stderr and exit 2, like argparse.error(). */
  error(message) {
    process.stderr.write(`${this.usage()}\n${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  /**
   * Parse argv (array of tokens, without node/script prefixes).
   * Returns an object with one property per option dest.
   */
  parseArgs(argv) {
    const values = {};
    const extras = [];
    const byName = new Map(this.options.map((o) => [o.name, o]));

    let i = 0;
    while (i < argv.length) {
      let token = argv[i];
      let inlineValue = null;

      if (token === '-h' || token === '--help') {
        this.printHelp();
        process.exit(0);
      }

      // Support the --name=value form.
      const eq = token.indexOf('=');
      if (isOptionLike(token) && eq !== -1) {
        inlineValue = token.slice(eq + 1);
        token = token.slice(0, eq);
      }

      const opt = byName.get(token);
      if (!opt) {
        extras.push(argv[i]); // unrecognized option or stray positional
        i += 1;
        continue;
      }

      let raw;
      if (inlineValue !== null) {
        raw = inlineValue;
        i += 1;
      } else {
        const next = argv[i + 1];
        if (next === undefined || isOptionLike(next)) {
          this.error(`argument ${opt.name}: expected one argument`);
        }
        raw = next;
        i += 2;
      }

      let value = raw;
      if (opt.typeFn) {
        value = opt.typeFn(raw);
        if (value === null || (typeof value === 'number' && Number.isNaN(value))) {
          this.error(`argument ${opt.name}: invalid int value: '${raw}'`);
        }
      }
      values[opt.dest] = value;
    }

    const missing = this.options
      .filter((o) => o.required && !(o.dest in values))
      .map((o) => o.name);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return values;
  }
}

