#!/usr/bin/env node
// test3.mjs — Node.js (ESM) port of /workspace/dataset/test3.py.
// Builds a 2-byte struct {field1: Int8ul, field2: Int8ul} from --a and --b
// and prints it exactly the way Python's print(bytes) would.

import { basename } from 'node:path';
import { ArgumentParser } from './lib/argparse.mjs';
import { parsePyInt } from './lib/pyint.mjs';
import { Struct, Int8ul, FormatFieldError } from './lib/construct.mjs';
import { reprBytes } from './lib/pybytes.mjs';

function main() {
  const parser = new ArgumentParser(basename(process.argv[1]));
  parser.addArgument('--a', { type: parsePyInt, required: true });
  parser.addArgument('--b', { type: parsePyInt, required: true });
  const args = parser.parseArgs(process.argv.slice(2));

  const structFormat = new Struct(
    ['field1', new Int8ul()], // 定义第一个字段
    ['field2', new Int8ul()], // 定义第二个字段
  );

  try {
    const data = structFormat.build({ field1: args.a, field2: args.b }); // 构建结构体
    console.log(reprBytes(data));
  } catch (err) {
    if (err instanceof FormatFieldError) {
      // Mirror the unhandled-exception path of the Python original (exit 1).
      process.stderr.write(`${err.name}: ${err.message}\n`);
      process.exit(1);
    }
    throw err;
  }
}

main();

